# Hindi / Gujarati text for History Ch 3 lesson, sections 4-6.
TEXT_B = {
 "s4.thm.title": ("16वीं सदी: सिकुड़ती दुनिया", "16મી સદી: નાનું થતું વિશ્વ"),
 "s4.thm.body": (
  "**सोलहवीं सदी** में, जब **यूरोपीय नाविकों ने एशिया तक का समुद्री मार्ग खोज लिया** और पश्चिमी सागर पार करके **अमेरिका** तक जा पहुँचे, तो आधुनिक युग से पहले की दुनिया बहुत छोटी हो गई।\n\n"
  "- सदियों से **हिंद महासागर** में व्यापार की हलचल थी, और माल, लोग, ज्ञान तथा रीति-रिवाज इसके पानी में आते-जाते रहते थे। **भारतीय उपमहाद्वीप** इन प्रवाहों के केंद्र में और उनके जाल का एक अहम बिंदु था। "
  "यूरोपीय लोगों के आने से इनमें से कुछ प्रवाह फैले या यूरोप की ओर मुड़ गए।\n"
  "- अपनी 'खोज' से पहले अमेरिका लाखों वर्षों से बाक़ी दुनिया के नियमित संपर्क से कटा हुआ था। 16वीं सदी से इसकी विशाल भूमि और भरपूर फ़सलों तथा खनिजों ने हर जगह व्यापार और जीवन को बदलना शुरू कर दिया।\n"
  "- आज के **पेरू और मेक्सिको** की खानों से निकली **क़ीमती धातुओं**, विशेषकर **चाँदी**, ने यूरोप की संपदा बढ़ाई और एशिया के साथ उसके व्यापार को धन दिया। 17वीं सदी के यूरोप में दक्षिण अमेरिका की अपार दौलत के क़िस्से फैले, और कई अभियान सोने के कल्पित शहर **एल डोराडो** की खोज में निकले।\n\n"
  "**हथियार के रूप में कीटाणु:** सोलहवीं सदी के मध्य तक **पुर्तगाली और स्पेनी** अमेरिका को जीतने और उपनिवेश बनाने में निर्णायक रूप से आगे बढ़ चुके थे। यूरोपीय विजय केवल बेहतर हथियारों का परिणाम नहीं थी। "
  "स्पेनी विजेताओं का सबसे शक्तिशाली हथियार कोई पारंपरिक सैन्य हथियार था ही नहीं: वह था **चेचक जैसे कीटाणु**, जो वे अपने साथ लेकर आए थे। लंबे अलगाव के कारण अमेरिका के मूल निवासियों में इन बीमारियों से लड़ने की **रोग-प्रतिरोधक क्षमता नहीं** थी। "
  "**चेचक** विशेष रूप से जानलेवा साबित हुई। एक बार आने के बाद यह महाद्वीप के भीतर तक, यूरोपीय लोगों के पहुँचने से भी पहले फैल गई। इसने पूरे के पूरे समुदायों को ख़त्म कर दिया और विजय का रास्ता साफ़ कर दिया। बंदूकें ख़रीदी या छीनी जा सकती थीं; चेचक जैसी बीमारियाँ नहीं।\n\n"
  "**यूरोप के धकेलने वाले कारण:** उन्नीसवीं सदी तक यूरोप में **ग़रीबी और भूख** आम थी। शहरों में भीड़ थी और **जानलेवा बीमारियाँ** फैली हुई थीं। धार्मिक टकराव आम थे और धार्मिक असहमति रखने वालों को सताया जाता था। **इसलिए हज़ारों लोग यूरोप छोड़कर अमेरिका भाग गए।** "
  "वहाँ अठारहवीं सदी तक **अफ़्रीका से पकड़े गए ग़ुलामों** से काम लेने वाले **बाग़ान** यूरोपीय बाज़ारों के लिए **कपास और चीनी** उगा रहे थे।\n\n"
  "**व्यापार का केंद्र पश्चिम की ओर:** अठारहवीं सदी के काफ़ी समय तक **चीन और भारत** दुनिया के सबसे धनी देशों में थे और एशियाई व्यापार में उनका दबदबा था। पर **पंद्रहवीं सदी** से चीन ने **बाहरी संपर्क सीमित** कर दिए और अलगाव में चला गया। "
  "चीन की घटती भूमिका और अमेरिका के बढ़ते महत्त्व से विश्व व्यापार का केंद्र धीरे-धीरे पश्चिम की ओर खिसक गया। **अब यूरोप विश्व व्यापार का केंद्र बन गया।**",
  "**સોળમી સદીમાં**, જ્યારે **યુરોપીય નાવિકોએ એશિયા સુધીનો દરિયાઈ માર્ગ શોધી કાઢ્યો** અને પશ્ચિમી મહાસાગર પાર કરીને **અમેરિકા** પહોંચ્યા, ત્યારે આધુનિક યુગ પહેલાંનું વિશ્વ ઘણું નાનું થઈ ગયું.\n\n"
  "- સદીઓથી **હિંદ મહાસાગર**માં વેપાર ધમધમતો હતો, અને માલ, લોકો, જ્ઞાન અને રિવાજો તેના પાણીમાં આવજા કરતાં. **ભારતીય ઉપખંડ** આ પ્રવાહોના કેન્દ્રમાં અને તેમના જાળાનું મહત્ત્વનું બિંદુ હતો. "
  "યુરોપીયનોના આગમનથી આમાંના કેટલાક પ્રવાહો વિસ્તર્યા કે યુરોપ તરફ વળ્યા.\n"
  "- પોતાની 'શોધ' પહેલાં અમેરિકા લાખો વર્ષોથી બાકીના વિશ્વ સાથેના નિયમિત સંપર્કથી કપાયેલું હતું. 16મી સદીથી તેની વિશાળ જમીન અને પુષ્કળ પાક તથા ખનિજોએ બધે વેપાર અને જીવન બદલવાનું શરૂ કર્યું.\n"
  "- આજના **પેરુ અને મેક્સિકો**ની ખાણોમાંથી નીકળેલી **કીમતી ધાતુઓ**, ખાસ કરીને **ચાંદી**, એ યુરોપની સંપત્તિ વધારી અને એશિયા સાથેના તેના વેપારને નાણાં પૂરાં પાડ્યાં. 17મી સદીના યુરોપમાં દક્ષિણ અમેરિકાની અઢળક સંપત્તિની વાતો ફેલાઈ, અને અનેક અભિયાનો સોનાના કલ્પિત શહેર **એલ ડોરાડો**ની શોધમાં નીકળ્યાં.\n\n"
  "**હથિયાર તરીકે જંતુઓ:** સોળમી સદીના મધ્ય સુધીમાં **પોર્ટુગીઝ અને સ્પેનિશ** લોકો અમેરિકાને જીતવા અને સંસ્થાન બનાવવામાં નિર્ણાયક રીતે આગળ વધી ચૂક્યા હતા. યુરોપીય વિજય ફક્ત ચડિયાતાં હથિયારોનું પરિણામ ન હતો. "
  "સ્પેનિશ વિજેતાઓનું સૌથી શક્તિશાળી હથિયાર કોઈ પરંપરાગત લશ્કરી હથિયાર હતું જ નહિ: તે હતું **શીતળા જેવા જંતુઓ**, જે તેઓ પોતાની સાથે લાવ્યા હતા. લાંબા અલગાવને કારણે અમેરિકાના મૂળ નિવાસીઓમાં આ રોગો સામે **રોગપ્રતિકારક શક્તિ ન** હતી. "
  "**શીતળા** ખાસ કરીને જીવલેણ સાબિત થયા. એક વાર આવ્યા પછી તે ખંડની અંદર સુધી, યુરોપીયનો પહોંચે તે પહેલાં જ ફેલાઈ ગયા. તેમણે આખા ને આખા સમુદાયોનો નાશ કર્યો અને વિજયનો માર્ગ મોકળો કર્યો. બંદૂકો ખરીદી કે છીનવી શકાય; શીતળા જેવા રોગો નહિ.\n\n"
  "**યુરોપમાંથી ધકેલતાં કારણો:** ઓગણીસમી સદી સુધી યુરોપમાં **ગરીબી અને ભૂખમરો** સામાન્ય હતાં. શહેરો ગીચ હતાં અને **જીવલેણ રોગો** ફેલાયેલા હતા. ધાર્મિક સંઘર્ષો સામાન્ય હતા અને ધાર્મિક મતભેદ ધરાવનારાઓ પર અત્યાચાર થતા. **તેથી હજારો લોકો યુરોપ છોડીને અમેરિકા ભાગી ગયા.** "
  "ત્યાં અઢારમી સદી સુધીમાં **આફ્રિકામાંથી પકડાયેલા ગુલામો** પાસે કામ કરાવતા **બગીચાઓ** યુરોપીય બજારો માટે **કપાસ અને ખાંડ** ઉગાડતા હતા.\n\n"
  "**વેપારનું કેન્દ્ર પશ્ચિમ તરફ:** અઢારમી સદી સુધી **ચીન અને ભારત** વિશ્વના સૌથી ધનિક દેશોમાં હતા અને એશિયાઈ વેપારમાં તેમનું વર્ચસ્વ હતું. પણ **પંદરમી સદી**થી ચીને **વિદેશી સંપર્કો મર્યાદિત** કર્યા અને અલગાવમાં સરકી ગયું. "
  "ચીનની ઘટતી ભૂમિકા અને અમેરિકાના વધતા મહત્ત્વથી વિશ્વ વેપારનું કેન્દ્ર ધીમે ધીમે પશ્ચિમ તરફ ખસ્યું. **હવે યુરોપ વિશ્વ વેપારનું કેન્દ્ર બન્યું.**"),
 "s4.table.title": ("16वीं सदी ने सब कुछ क्यों बदल दिया", "16મી સદીએ બધું કેમ બદલી નાખ્યું"),
 "s4.table.body": (
  "| कारण | 16वीं सदी में इसने दुनिया को कैसे बदला |\n|---|---|\n| समुद्री मार्ग | यूरोपीय नाविकों ने एशिया का समुद्री मार्ग खोजा और पश्चिमी सागर पार करके अमेरिका पहुँचे |\n"
  "| चाँदी | आज के पेरू और मेक्सिको की खानों की चाँदी ने यूरोप की संपदा बढ़ाई और एशिया के साथ व्यापार का ख़र्च उठाया |\n"
  "| कीटाणु | स्पेनियों के साथ आई चेचक ने अमेरिका के मूल निवासियों को मारा, जिनमें प्रतिरोधक क्षमता नहीं थी: बंदूकों से भी ताक़तवर हथियार |\n"
  "| यूरोप के धकेलने वाले कारण | ग़रीबी, भूख, भीड़भरे शहर, जानलेवा बीमारियाँ और धार्मिक उत्पीड़न ने हज़ारों को अमेरिका भागने पर मजबूर किया |\n"
  "| बाग़ान | अफ़्रीका से पकड़े गए ग़ुलाम अमेरिका में यूरोपीय बाज़ारों के लिए कपास और चीनी उगाते थे |\n| चीन का अलगाव | 15वीं सदी से चीन ने बाहरी संपर्क सीमित किए; विश्व व्यापार का केंद्र पश्चिम में यूरोप की ओर खिसक गया |",
  "| કારણ | 16મી સદીમાં તેણે વિશ્વને કેવી રીતે બદલ્યું |\n|---|---|\n| દરિયાઈ માર્ગો | યુરોપીય નાવિકોએ એશિયાનો દરિયાઈ માર્ગ શોધ્યો અને પશ્ચિમી મહાસાગર પાર કરીને અમેરિકા પહોંચ્યા |\n"
  "| ચાંદી | આજના પેરુ અને મેક્સિકોની ખાણોની ચાંદીએ યુરોપની સંપત્તિ વધારી અને એશિયા સાથેના વેપારનો ખર્ચ ઉપાડ્યો |\n"
  "| જંતુઓ | સ્પેનિશ લોકો સાથે આવેલા શીતળાએ અમેરિકાના મૂળ નિવાસીઓને માર્યા, જેમનામાં પ્રતિકારક શક્તિ ન હતી: બંદૂકો કરતાં પણ શક્તિશાળી હથિયાર |\n"
  "| યુરોપમાંથી ધકેલતાં કારણો | ગરીબી, ભૂખ, ગીચ શહેરો, જીવલેણ રોગો અને ધાર્મિક અત્યાચારે હજારોને અમેરિકા ભાગવા મજબૂર કર્યા |\n"
  "| બગીચાઓ | આફ્રિકામાંથી પકડાયેલા ગુલામો અમેરિકામાં યુરોપીય બજારો માટે કપાસ અને ખાંડ ઉગાડતા |\n| ચીનનો અલગાવ | 15મી સદીથી ચીને વિદેશી સંપર્કો મર્યાદિત કર્યા; વિશ્વ વેપારનું કેન્દ્ર પશ્ચિમમાં યુરોપ તરફ ખસ્યું |"),

 "s5.note.title": ("आपकी परियोजना के लिए, बोर्ड पेपर के लिए नहीं", "તમારા પ્રોજેક્ટ માટે, બોર્ડ પેપર માટે નહિ"),
 "s5.note.body": (
  "CBSE 2025-26 पाठ्यक्रम में इस अध्याय के केवल **उपविषय 1 से 1.3** की बोर्ड परीक्षा होती है। "
  "उपविषय **2 से 4.4** (उन्नीसवीं सदी, 1815–1914, से ब्रेटन वुड्स के अंत और 'वैश्वीकरण' की शुरुआत तक) भूगोल अध्याय 7 (राष्ट्रीय अर्थव्यवस्था की जीवन रेखाएँ) और अर्थशास्त्र अध्याय 4 (वैश्वीकरण) के साथ एक **अंतर्विषयक परियोजना** हैं, जिसका आंतरिक मूल्यांकन 5 अंकों का होता है। "
  "नीचे दिया सारांश उस परियोजना में आपकी मदद करेगा।",
  "CBSE 2025-26 અભ્યાસક્રમમાં આ પ્રકરણના ફક્ત **પેટાવિષય 1થી 1.3**ની બોર્ડ પરીક્ષા લેવાય છે. "
  "પેટાવિષય **2થી 4.4** (ઓગણીસમી સદી, 1815–1914, થી બ્રેટન વુડ્સના અંત અને 'વૈશ્વિકીકરણ'ની શરૂઆત સુધી) ભૂગોળ પ્રકરણ 7 (રાષ્ટ્રીય અર્થતંત્રની જીવાદોરીઓ) અને અર્થશાસ્ત્ર પ્રકરણ 4 (વૈશ્વિકીકરણ) સાથે એક **આંતરવિષયક પ્રોજેક્ટ** છે, જેનું આંતરિક મૂલ્યાંકન 5 ગુણનું હોય છે. "
  "નીચેનો સારાંશ એ પ્રોજેક્ટમાં તમને મદદ કરશે."),
 "s5.table.title": ("परियोजना के विषय एक नज़र में", "પ્રોજેક્ટના વિષયો એક નજરે"),
 "s5.table.body": (
  "| काल (परियोजना विषय) | मुख्य तथ्य |\n|---|---|\n| 1815–1914: विश्व अर्थव्यवस्था का उदय | तीन प्रवाह: व्यापार, श्रम और पूँजी। ब्रिटेन ने कॉर्न लॉ समाप्त किए; लगभग 5 करोड़ लोग यूरोप से अमेरिका और ऑस्ट्रेलिया गए; रेलवे, भाप के जहाज़, टेलीग्राफ़ और प्रशीतित जहाज़ों ने बाज़ारों को जोड़ा |\n"
  "| उपनिवेशवाद | बर्लिन सम्मेलन (1885) में अफ़्रीका का बँटवारा; **रिंडरपेस्ट** (1890 का दशक) ने अफ़्रीका के लगभग 90% मवेशी मार डाले, जिससे अफ़्रीकी लोग मज़दूरी करने को मजबूर हुए |\n"
  "| गिरमिटिया श्रम | पूर्वी उत्तर प्रदेश, बिहार, मध्य भारत और तमिलनाडु के भारतीय मज़दूर कैरिबियन (त्रिनिदाद, गयाना, सूरीनाम), मॉरीशस और फ़िजी गए; होसे उत्सव, चटनी संगीत; गिरमिटिया प्रथा **1921** में समाप्त |\n"
  "| भारतीय उद्यमी | शिकारीपुरी श्रॉफ़ और नट्टुकोट्टई चेट्टियार ने मध्य और दक्षिण-पूर्व एशिया में निर्यात कृषि को ऋण दिया |\n"
  "| दो महायुद्धों के बीच अर्थव्यवस्था | प्रथम विश्व युद्ध (1914–18); अमेरिका अंतरराष्ट्रीय ऋणदाता बना; **महामंदी** लगभग 1929 में शुरू हुई; भारत में 1928 से 1934 के बीच गेहूँ की क़ीमत 50% गिरी |\n"
  "| युद्धोत्तर काल | **ब्रेटन वुड्स सम्मेलन (जुलाई 1944)** ने IMF और विश्व बैंक बनाए; निश्चित विनिमय दरें, डॉलर सोने से 35 अमेरिकी डॉलर प्रति औंस पर बँधा; बाद में उपनिवेशों की स्वतंत्रता, G-77 और वैश्वीकरण |",
  "| સમયગાળો (પ્રોજેક્ટ વિષય) | મુખ્ય તથ્યો |\n|---|---|\n| 1815–1914: વિશ્વ અર્થતંત્રનો ઉદય | ત્રણ પ્રવાહો: વેપાર, શ્રમ અને મૂડી. બ્રિટને કૉર્ન લૉઝ નાબૂદ કર્યા; આશરે 5 કરોડ લોકો યુરોપથી અમેરિકા અને ઑસ્ટ્રેલિયા ગયા; રેલવે, વરાળનાં જહાજો, તાર અને રેફ્રિજરેટેડ જહાજોએ બજારોને જોડ્યાં |\n"
  "| સંસ્થાનવાદ | બર્લિન પરિષદ (1885)માં આફ્રિકાની વહેંચણી; **રિન્ડરપેસ્ટ** (1890નો દાયકો)એ આફ્રિકાનાં આશરે 90% ઢોર માર્યાં, જેથી આફ્રિકનો મજૂરી કરવા મજબૂર બન્યા |\n"
  "| કરારબદ્ધ (ગિરમીટિયા) શ્રમ | પૂર્વ ઉત્તર પ્રદેશ, બિહાર, મધ્ય ભારત અને તમિળનાડુના ભારતીય મજૂરો કેરેબિયન (ત્રિનિદાદ, ગુયાના, સુરીનામ), મોરિશિયસ અને ફિજી ગયા; હોસે ઉત્સવ, ચટણી સંગીત; કરારબદ્ધ પ્રથા **1921**માં નાબૂદ |\n"
  "| ભારતીય ઉદ્યોગસાહસિકો | શિકારીપુરી શ્રોફ અને નટ્ટુકોટ્ટઈ ચેટ્ટિયારોએ મધ્ય અને અગ્નિ એશિયામાં નિકાસલક્ષી ખેતીને ધિરાણ આપ્યું |\n"
  "| બે મહાયુદ્ધો વચ્ચેનું અર્થતંત્ર | પ્રથમ વિશ્વયુદ્ધ (1914–18); અમેરિકા આંતરરાષ્ટ્રીય લેણદાર બન્યું; **મહામંદી** આશરે 1929માં શરૂ થઈ; ભારતમાં 1928થી 1934 વચ્ચે ઘઉંના ભાવ 50% ઘટ્યા |\n"
  "| યુદ્ધ પછીનો સમય | **બ્રેટન વુડ્સ પરિષદ (જુલાઈ 1944)**એ IMF અને વિશ્વ બૅન્ક સ્થાપ્યાં; સ્થિર વિનિમય દરો, ડૉલર સોના સાથે 35 અમેરિકન ડૉલર પ્રતિ ઔંસે બંધાયો; પછીથી સંસ્થાનોની સ્વતંત્રતા, G-77 અને વૈશ્વિકીકરણ |"),

 "s6.memory.title": ("याद रखने की तरकीबें", "યાદ રાખવાની યુક્તિઓ"),
 "s6.memory.body": (
  "- **रेशम मार्ग = \"रेशम पश्चिम को, चाँदी पूरब को, बुद्ध हर दिशा में।\"**\n- **अमेरिका के उपहार:** आलू, टमाटर, मक्का, मिर्च, मूँगफली, शकरकंद (और सोया): \"आ-ट-म-मि-मू-श\"।\n"
  "- **16वीं सदी = 3 स:** **स**मुद्री मार्ग, पेरू और मेक्सिको की **चाँदी**, और **चेचक**।\n- **यूरोप से धकेलने वाले कारण = ग़-भू-बी-ध:** **ग़**रीबी, **भू**ख, **बी**मारी, **ध**ार्मिक उत्पीड़न।",
  "- **રેશમ માર્ગો = \"રેશમ પશ્ચિમે, ચાંદી પૂર્વે, બુદ્ધ દરેક દિશામાં.\"**\n- **અમેરિકાની ભેટ:** બટાકા, ટામેટાં, મકાઈ, મરચાં, મગફળી, શક્કરિયાં (અને સોયા): \"બ-ટા-મ-મ-મ-શ\".\n"
  "- **16મી સદી = 3 મુદ્દા:** **દરિયાઈ** માર્ગ, પેરુ અને મેક્સિકોની **ચાંદી**, અને **શીતળા**.\n- **યુરોપમાંથી ધકેલતાં કારણો = ગ-ભૂ-રો-ધ:** **ગ**રીબી, **ભૂ**ખ, **રો**ગ, **ધ**ાર્મિક અત્યાચાર."),
 "s6.mistakes.title": ("सामान्य गलतियाँ", "સામાન્ય ભૂલો"),
 "s6.mistakes.body": (
  "1. कहना कि रेशम मार्गों पर केवल रेशम जाता था: उन पर पॉटरी, कपड़े, मसाले, क़ीमती धातुएँ, धर्म और लोग भी आते-जाते थे।\n2. लिखना कि आलू और मिर्च भारत की मूल फ़सलें हैं: ये अमेरिका से आईं।\n"
  "3. कहना कि स्पेनियों ने अमेरिका मुख्यतः बंदूकों से जीता: चेचक जैसे कीटाणु उनका सबसे शक्तिशाली हथियार थे।\n4. कहना कि रेशम मार्गों पर सोना एशिया से यूरोप गया: क़ीमती धातुएँ **यूरोप से एशिया** आईं।\n"
  "5. लिखना कि चीन ने 15वीं सदी से व्यापार बढ़ाया: उसने बाहरी संपर्क **सीमित** किए।\n6. ब्रेटन वुड्स और महामंदी को बोर्ड परीक्षा के लिए रटना: 2025-26 में ये **परियोजना** विषय हैं।",
  "1. કહેવું કે રેશમ માર્ગો પર ફક્ત રેશમ જતું: તેના પર માટીનાં વાસણો, કાપડ, મસાલા, કીમતી ધાતુઓ, ધર્મો અને લોકો પણ આવજા કરતાં.\n2. લખવું કે બટાકા અને મરચાં ભારતના મૂળ પાક છે: તે અમેરિકાથી આવ્યાં.\n"
  "3. કહેવું કે સ્પેનિશ લોકોએ અમેરિકા મુખ્યત્વે બંદૂકોથી જીત્યું: શીતળા જેવા જંતુઓ તેમનું સૌથી શક્તિશાળી હથિયાર હતા.\n4. કહેવું કે રેશમ માર્ગો પર સોનું એશિયાથી યુરોપ ગયું: કીમતી ધાતુઓ **યુરોપથી એશિયા** આવી.\n"
  "5. લખવું કે ચીને 15મી સદીથી વેપાર વધાર્યો: તેણે વિદેશી સંપર્કો **મર્યાદિત** કર્યા.\n6. બ્રેટન વુડ્સ અને મહામંદીને બોર્ડ પરીક્ષા માટે ગોખવાં: 2025-26માં તે **પ્રોજેક્ટ** વિષયો છે."),
 "s6.tip.title": ("कक्षा में करके देखिए", "વર્ગમાં કરી જુઓ"),
 "s6.tip.body": ("'रसोई का पुरातत्त्व' गतिविधि कराइए: विद्यार्थी घर में इस्तेमाल होने वाली दस सामग्रियों की सूची बनाएँ और पता करें कि हर एक पहले कहाँ से आई। उन्हें विश्व मानचित्र पर तीरों से दर्शाएँ। फिर चर्चा कीजिए: अमेरिका के बिना भारतीय भोजन कैसा होता?",
                 "'રસોડાનું પુરાતત્ત્વ' પ્રવૃત્તિ કરાવો: વિદ્યાર્થીઓ ઘરમાં વપરાતી દસ સામગ્રીની યાદી બનાવે અને શોધે કે દરેક પહેલાં ક્યાંથી આવી. તેમને વિશ્વના નકશા પર તીરથી દર્શાવે. પછી ચર્ચા કરો: અમેરિકા વિના ભારતીય ખોરાક કેવો હોત?"),
 "s6.reflection.title": ("सोचिए और समझाइए", "વિચારો અને સમજાવો"),
 "s6.reflection.body": ("इतिहासकार क्यों कहते हैं कि अमेरिका को बंदूकों ने नहीं, कीटाणुओं ने जीता? तीन वाक्यों में समझाइए।", "ઇતિહાસકારો કેમ કહે છે કે અમેરિકાને બંદૂકોએ નહિ, જંતુઓએ જીત્યું? ત્રણ વાક્યોમાં સમજાવો."),
 "s6.connection.title": ("यह कहाँ ले जाता है", "આ ક્યાં લઈ જાય છે"),
 "s6.connection.body": (
  "- **भूगोल अध्याय 7, राष्ट्रीय अर्थव्यवस्था की जीवन रेखाएँ** और **अर्थशास्त्र अध्याय 4, वैश्वीकरण:** ये इस अध्याय के साथ अंतर्विषयक परियोजना बनाते हैं।\n"
  "- **विज्ञान, अध्याय 13 (हमारा पर्यावरण) और स्वास्थ्य:** प्रतिरोधक क्षमता न होने पर आबादी में बीमारियों का फैलना।\n- **अध्याय 1:** यूरोपीय राष्ट्र-राज्य ही औपनिवेशिक शक्तियाँ बने जिन्होंने विश्व व्यापार को नया रूप दिया।",
  "- **ભૂગોળ પ્રકરણ 7, રાષ્ટ્રીય અર્થતંત્રની જીવાદોરીઓ** અને **અર્થશાસ્ત્ર પ્રકરણ 4, વૈશ્વિકીકરણ:** આ પ્રકરણ સાથે આંતરવિષયક પ્રોજેક્ટ બનાવે છે.\n"
  "- **વિજ્ઞાન, પ્રકરણ 13 (આપણું પર્યાવરણ) અને આરોગ્ય:** પ્રતિકારક શક્તિ ન હોય ત્યારે વસ્તીમાં રોગોનો ફેલાવો.\n- **પ્રકરણ 1:** યુરોપીય રાષ્ટ્ર-રાજ્યો જ સંસ્થાનવાદી સત્તાઓ બન્યાં જેમણે વિશ્વ વેપારને નવું સ્વરૂપ આપ્યું."),
 "s6.mastery.title": ("निपुणता चुनौती", "નિપુણતા પડકાર"),
 "s6.mastery.body": (
  "'सोलहवीं सदी में आधुनिक युग से पहले की दुनिया नाटकीय रूप से बदल गई।' लगभग 60 शब्दों में तीन बिंदुओं से समझाइए।\n\n"
  "**आदर्श उत्तर:** यूरोपीय नाविकों ने एशिया का समुद्री मार्ग खोजा और पश्चिमी सागर पार करके अमेरिका पहुँचे। पेरू और मेक्सिको की खानों की चाँदी ने यूरोप की संपदा बढ़ाई और एशिया के साथ उसके व्यापार का ख़र्च उठाया। "
  "चेचक जैसे कीटाणुओं ने अमेरिका के मूल निवासियों को, जिनमें प्रतिरोधक क्षमता नहीं थी, ख़त्म कर दिया और पुर्तगाली तथा स्पेनी उपनिवेशों का रास्ता खोला; अफ़्रीकी ग़ुलामों से चलने वाले बाग़ान यूरोप के लिए कपास और चीनी उगाने लगे, और विश्व व्यापार का केंद्र पश्चिम में यूरोप की ओर खिसक गया।",
  "'સોળમી સદીમાં આધુનિક યુગ પહેલાંનું વિશ્વ નાટ્યાત્મક રીતે બદલાયું.' આશરે 60 શબ્દોમાં ત્રણ મુદ્દાથી સમજાવો.\n\n"
  "**આદર્શ જવાબ:** યુરોપીય નાવિકોએ એશિયાનો દરિયાઈ માર્ગ શોધ્યો અને પશ્ચિમી મહાસાગર પાર કરીને અમેરિકા પહોંચ્યા. પેરુ અને મેક્સિકોની ખાણોની ચાંદીએ યુરોપની સંપત્તિ વધારી અને એશિયા સાથેના તેના વેપારનો ખર્ચ ઉપાડ્યો. "
  "શીતળા જેવા જંતુઓએ અમેરિકાના મૂળ નિવાસીઓને, જેમનામાં પ્રતિકારક શક્તિ ન હતી, નષ્ટ કર્યા અને પોર્ટુગીઝ તથા સ્પેનિશ સંસ્થાનોનો માર્ગ ખોલ્યો; આફ્રિકન ગુલામોથી ચાલતા બગીચાઓ યુરોપ માટે કપાસ અને ખાંડ ઉગાડવા લાગ્યા, અને વિશ્વ વેપારનું કેન્દ્ર પશ્ચિમમાં યુરોપ તરફ ખસ્યું."),
 "s6.summary.title": ("अध्याय सारांश", "પ્રકરણ સારાંશ"),
 "s6.summary.body": (
  "- रेशम मार्ग (ईसा पूर्व से लगभग 15वीं सदी तक) एशिया को यूरोप और उत्तरी अफ़्रीका से जोड़ते थे; रेशम, पॉटरी, कपड़े और मसाले पश्चिम गए, सोना और चाँदी पूरब आए; इन मार्गों से बौद्ध, ईसाई और इस्लाम धर्म फैले।\n"
  "- भोजन ने यात्रा की: चीन से नूडल्स (शायद सिसली तक पास्ता); अमेरिका से आलू, मक्का, टमाटर, मिर्च, मूँगफली और शकरकंद; आलू ने यूरोप के ग़रीबों को बचाया, पर 1840 के दशक में इसकी बर्बादी से आयरलैंड में अकाल पड़ा।\n"
  "- 16वीं सदी में यूरोपीय लोगों ने एशिया और अमेरिका के समुद्री मार्ग खोजे; पेरू और मेक्सिको की चाँदी ने यूरोप को धनी बनाया; चेचक ने अमेरिका के मूल निवासियों को नष्ट किया; ग़रीबी, बीमारी और उत्पीड़न ने यूरोपीय लोगों को अमेरिका धकेला; अफ़्रीकी ग़ुलामों ने बाग़ानों में काम किया।\n"
  "- चीन के अलगाव और अमेरिका के उदय से विश्व व्यापार का केंद्र यूरोप बन गया।\n- 1815 से ब्रेटन वुड्स के अंत तक का काल 2025-26 में अंतर्विषयक परियोजना का विषय है।",
  "- રેશમ માર્ગો (ઈ.સ. પૂર્વેથી આશરે 15મી સદી સુધી) એશિયાને યુરોપ અને ઉત્તર આફ્રિકા સાથે જોડતા; રેશમ, માટીનાં વાસણો, કાપડ અને મસાલા પશ્ચિમે ગયાં, સોનું અને ચાંદી પૂર્વે આવ્યાં; આ માર્ગોએ બૌદ્ધ, ખ્રિસ્તી અને ઇસ્લામ ધર્મ ફેલાયા.\n"
  "- ખોરાકે યાત્રા કરી: ચીનથી નૂડલ્સ (કદાચ સિસિલી સુધી પાસ્તા); અમેરિકાથી બટાકા, મકાઈ, ટામેટાં, મરચાં, મગફળી અને શક્કરિયાં; બટાકાએ યુરોપના ગરીબોને બચાવ્યા, પણ 1840ના દાયકામાં તેના નાશથી આયર્લૅન્ડમાં દુકાળ પડ્યો.\n"
  "- 16મી સદીમાં યુરોપીયનોએ એશિયા અને અમેરિકાના દરિયાઈ માર્ગો શોધ્યા; પેરુ અને મેક્સિકોની ચાંદીએ યુરોપને ધનિક બનાવ્યું; શીતળાએ અમેરિકાના મૂળ નિવાસીઓનો નાશ કર્યો; ગરીબી, રોગ અને અત્યાચારે યુરોપીયનોને અમેરિકા તરફ ધકેલ્યા; આફ્રિકન ગુલામોએ બગીચાઓમાં કામ કર્યું.\n"
  "- ચીનના અલગાવ અને અમેરિકાના ઉદયથી વિશ્વ વેપારનું કેન્દ્ર યુરોપ બન્યું.\n- 1815થી બ્રેટન વુડ્સના અંત સુધીનો સમય 2025-26માં આંતરવિષયક પ્રોજેક્ટનો વિષય છે."),
 "s6.examtips.title": ("बोर्ड परीक्षा के सुझाव", "બોર્ડ પરીક્ષા માટે સૂચનો"),
 "s6.examtips.body": (
  "- इस अध्याय के प्रश्न आधुनिक युग से पहले की दुनिया तक सीमित हैं: रेशम मार्ग, भोजन की यात्रा, और विजय, बीमारी तथा व्यापार।\n- 2025-26 के नमूना प्रश्न-पत्र में पूछा गया: व्यापारिक और सांस्कृतिक संबंधों के उदाहरण के रूप में रेशम मार्ग (2 अंक), और नई फ़सलें जीवन और मृत्यु का अंतर क्यों बनीं (2 अंक)।\n"
  "- हर 2 अंक के उत्तर में दो ठोस उदाहरण दीजिए (जैसे चीनी रेशम और पॉटरी; बौद्ध धर्म)।\n- प्रवाहों की दिशा याद रखिए: रेशम पश्चिम को, सोना और चाँदी पूरब को।",
  "- આ પ્રકરણના પ્રશ્નો આધુનિક યુગ પહેલાંના વિશ્વ સુધી મર્યાદિત છે: રેશમ માર્ગો, ખોરાકની યાત્રા, અને વિજય, રોગ તથા વેપાર.\n- 2025-26ના નમૂના પ્રશ્નપત્રમાં પુછાયું: વેપારી અને સાંસ્કૃતિક સંબંધોના ઉદાહરણ તરીકે રેશમ માર્ગો (2 ગુણ), અને નવા પાક જીવન અને મૃત્યુનો તફાવત કેમ બન્યા (2 ગુણ).\n"
  "- દરેક 2 ગુણના જવાબમાં બે ચોક્કસ ઉદાહરણો આપો (જેમ કે ચીની રેશમ અને માટીનાં વાસણો; બૌદ્ધ ધર્મ).\n- પ્રવાહોની દિશા યાદ રાખો: રેશમ પશ્ચિમે, સોનું અને ચાંદી પૂર્વે."),
 "s6.flash1.front": ("इन्हें 'रेशम मार्ग' क्यों कहते हैं?", "તેમને 'રેશમ માર્ગો' કેમ કહે છે?"),
 "s6.flash1.back": ("इन मार्गों से पश्चिम भेजे जाने वाले चीनी रेशम के महत्त्व के कारण।", "આ માર્ગે પશ્ચિમ મોકલાતા ચીની રેશમના મહત્ત્વને કારણે."),
 "s6.flash2.front": ("अमेरिका से आए चार खाद्य पदार्थों के नाम बताइए।", "અમેરિકાથી આવેલા ચાર ખાદ્યપદાર્થોનાં નામ આપો."),
 "s6.flash2.back": ("आलू, मक्का, टमाटर, मिर्च (साथ में मूँगफली, सोया, शकरकंद)।", "બટાકા, મકાઈ, ટામેટાં, મરચાં (સાથે મગફળી, સોયા, શક્કરિયાં)."),
 "s6.flash3.front": ("यूरोप को धनी बनाने वाली चाँदी कहाँ से आई?", "યુરોપને ધનિક બનાવનારી ચાંદી ક્યાંથી આવી?"),
 "s6.flash3.back": ("आज के पेरू और मेक्सिको की खानों से।", "આજના પેરુ અને મેક્સિકોની ખાણોમાંથી."),
 "s6.flash4.front": ("चेचक ने इतने अमेरिकी इंडियनों को क्यों मारा?", "શીતળાએ આટલા અમેરિકન ઇન્ડિયનોને કેમ માર્યા?"),
 "s6.flash4.back": ("वे इतने लंबे समय तक अलग-थलग रहे थे कि उनमें यूरोपीय बीमारियों के प्रति प्रतिरोधक क्षमता नहीं थी।", "તેઓ એટલા લાંબા સમય સુધી અલગ રહ્યા હતા કે તેમનામાં યુરોપીય રોગો સામે પ્રતિકારક શક્તિ ન હતી."),
}
